package ncasa.expense.infrastructure.scheduling;
import java.time.Clock;import ncasa.expense.application.occurrence.*;import ncasa.expense.application.reminder.PublishDueExpensePlanReminderUseCase;import ncasa.expense.application.port.out.ExpensePlanRepository;import ncasa.expense.infrastructure.config.ExpensePlanProperties;import ncasa.expense.domain.ExpensePlanId;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ExpensePlanScheduledJobs{private final ExpensePlanRepository plans;private final ExpensePlanJobRunner runner;private final DispatchOutboxMessagesUseCase outbox;private final Clock clock;private final ExpensePlanProperties properties;public ExpensePlanScheduledJobs(ExpensePlanRepository p,ExpensePlanJobRunner r,DispatchOutboxMessagesUseCase o,Clock c,ExpensePlanProperties x){plans=p;runner=r;outbox=o;clock=c;properties=x;}@Scheduled(fixedDelayString="${ncasa.expense-plans.reminder-delay:1m}")void reminders(){plans.findReminderDueIds(clock.instant(),properties.batchSize()).forEach(runner::remind);}@Scheduled(fixedDelayString="${ncasa.expense-plans.generation-delay:1m}")void materialize(){plans.findDueIds(clock.instant(),properties.batchSize()).forEach(runner::materialize);}@Scheduled(fixedDelayString="${ncasa.outbox.dispatch-delay:5s}")void dispatch(){outbox.execute();}}
